use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl < 'c , 'a , G , A > SccsConstruction < 'c , 'a , G , A > where G : DirectedGraph + Successors , A : Annotations < G :: Node > , { # [doc = " Identifies SCCs in the graph `G` and computes the resulting"] # [doc = " DAG. This uses a variant of [Tarjan's"] # [doc = " algorithm][wikipedia]. The high-level summary of the algorithm"] # [doc = " is that we do a depth-first search. Along the way, we keep a"] # [doc = " stack of each node whose successors are being visited. We"] # [doc = " track the depth of each node on this stack (there is no depth"] # [doc = " if the node is not on the stack). When we find that some node"] # [doc = " N with depth D can reach some other node N' with lower depth"] # [doc = " D' (i.e., D' < D), we know that N, N', and all nodes in"] # [doc = " between them on the stack are part of an SCC."] # [doc = ""] # [doc = " Additionally, we keep track of a current annotation of the SCC."] # [doc = ""] # [doc = " [wikipedia]: https://bit.ly/2EZIx84"] fn construct (graph : & 'c G , annotations : & 'a mut A) -> Sccs < G :: Node , A :: SccIdx > { let num_nodes = graph . num_nodes () ; let mut this = Self { graph , node_states : IndexVec :: from_elem_n (NodeState :: NotVisited , num_nodes) , node_stack : Vec :: with_capacity (num_nodes) , successors_stack : Vec :: new () , scc_data : SccData { scc_details : IndexVec :: new () , all_successors : Vec :: new () } , duplicate_set : FxHashSet :: default () , annotations , } ; let scc_indices = graph . iter_nodes () . map (| node | match this . start_walk_from (node) { WalkReturn :: Complete { scc_index , .. } => scc_index , WalkReturn :: Cycle { min_depth , .. } => { panic ! ("`start_walk_node({node:?})` returned cycle with depth {min_depth:?}") } }) . collect () ; Sccs { scc_indices , scc_data : this . scc_data } } fn start_walk_from (& mut self , node : G :: Node) -> WalkReturn < A :: SccIdx , A :: Ann > { self . inspect_node (node) . unwrap_or_else (| | self . walk_unvisited_node (node)) } # [doc = " Inspect a node during the DFS. We first examine its current"] # [doc = " state -- if it is not yet visited (`NotVisited`), return `None` so"] # [doc = " that the caller might push it onto the stack and start walking its"] # [doc = " successors."] # [doc = ""] # [doc = " If it is already on the DFS stack it will be in the state"] # [doc = " `BeingVisited`. In that case, we have found a cycle and we"] # [doc = " return the depth from the stack."] # [doc = ""] # [doc = " Otherwise, we are looking at a node that has already been"] # [doc = " completely visited. We therefore return `WalkReturn::Complete`"] # [doc = " with its associated SCC index."] fn inspect_node (& mut self , node : G :: Node) -> Option < WalkReturn < A :: SccIdx , A :: Ann > > { Some (match self . find_state (node) { NodeState :: InCycle { scc_index , annotation } => { WalkReturn :: Complete { scc_index , annotation } } NodeState :: BeingVisited { depth : min_depth , annotation } => { WalkReturn :: Cycle { min_depth , annotation } } NodeState :: NotVisited => return None , NodeState :: InCycleWith { parent } => panic ! ("`find_state` returned `InCycleWith({parent:?})`, which ought to be impossible") , }) } # [doc = " Fetches the state of the node `r`. If `r` is recorded as being"] # [doc = " in a cycle with some other node `r2`, then fetches the state"] # [doc = " of `r2` (and updates `r` to reflect current result). This is"] # [doc = " basically the \"find\" part of a standard union-find algorithm"] # [doc = " (with path compression)."] fn find_state (& mut self , mut node : G :: Node) -> NodeState < G :: Node , A :: SccIdx , A :: Ann > { let mut previous_node = node ; let (root_state , assigned_state) = { loop { trace ! ("find_state(r = {node:?} in state {:?})" , self . node_states [node]) ; match self . node_states [node] { s @ NodeState :: NotVisited => return s , s @ NodeState :: InCycle { .. } => break (s , s) , s @ NodeState :: BeingVisited { depth , .. } => { break (s , NodeState :: InCycleWith { parent : self . node_stack [depth] }) ; } NodeState :: InCycleWith { parent } => { assert ! (node != parent , "Node can not be in cycle with itself") ; self . node_states [node] = NodeState :: InCycleWith { parent : previous_node } ; previous_node = node ; node = parent ; } } } } ; loop { if previous_node == node { return root_state ; } trace ! ("Compressing {node:?} down to {previous_node:?} with state {assigned_state:?}") ; match self . node_states [previous_node] { NodeState :: InCycleWith { parent : previous } => { node = previous_node ; previous_node = previous ; } other => unreachable ! ("Invalid previous link while compressing cycle: {other:?}") , } self . node_states [node] = assigned_state ; } } # [doc = " Walks a node that has never been visited before."] # [doc = ""] # [doc = " Call this method when `inspect_node` has returned `None`. Having the"] # [doc = " caller decide avoids mutual recursion between the two methods and allows"] # [doc = " us to maintain an allocated stack for nodes on the path between calls."] # [instrument (skip (self , initial) , level = "trace")] fn walk_unvisited_node (& mut self , initial : G :: Node) -> WalkReturn < A :: SccIdx , A :: Ann > { trace ! ("Walk unvisited node: {initial:?}") ; struct VisitingNodeFrame < G : DirectedGraph , Successors , A > { node : G :: Node , successors : Option < Successors > , depth : usize , min_depth : usize , successors_len : usize , min_cycle_root : G :: Node , successor_node : G :: Node , # [doc = " The annotation for the SCC starting in `node`. It may or may"] # [doc = " not contain other nodes."] current_component_annotation : A , } let mut successors_stack = core :: mem :: take (& mut self . successors_stack) ; debug_assert_eq ! (successors_stack . len () , 0) ; let mut stack : Vec < VisitingNodeFrame < G , _ , _ > > = vec ! [VisitingNodeFrame { node : initial , depth : 0 , min_depth : 0 , successors : None , successors_len : 0 , min_cycle_root : initial , successor_node : initial , current_component_annotation : self . annotations . new (initial) , }] ; let mut return_value = None ; 'recurse : while let Some (frame) = stack . last_mut () { let VisitingNodeFrame { node , depth , successors , successors_len , min_depth , min_cycle_root , successor_node , current_component_annotation , } = frame ; let node = * node ; let depth = * depth ; trace ! ("Visiting {node:?} at depth {depth:?}, annotation: {current_component_annotation:?}") ; let successors = match successors { Some (successors) => successors , None => { trace ! (? depth , ? node) ; debug_assert_matches ! (self . node_states [node] , NodeState :: NotVisited) ; self . node_states [node] = NodeState :: BeingVisited { depth , annotation : * current_component_annotation , } ; self . node_stack . push (node) ; * successors_len = successors_stack . len () ; successors . get_or_insert (self . graph . successors (node)) } } ; let successors_len = * successors_len ; let returned_walk = return_value . take () . into_iter () . map (| walk | (* successor_node , Some (walk))) ; let successor_walk = successors . map (| successor_node | { trace ! (? node , ? successor_node) ; (successor_node , self . inspect_node (successor_node)) }) ; for (successor_node , walk) in returned_walk . chain (successor_walk) { match walk { Some (WalkReturn :: Cycle { min_depth : successor_min_depth , annotation : successor_annotation , }) => { trace ! ("Cycle found from {node:?}, minimum depth: {successor_min_depth:?}, annotation: {successor_annotation:?}") ; assert ! (successor_min_depth <= depth) ; if successor_min_depth < * min_depth { trace ! (? node , ? successor_min_depth) ; * min_depth = successor_min_depth ; * min_cycle_root = successor_node ; } current_component_annotation . update_scc (successor_annotation) ; } Some (WalkReturn :: Complete { scc_index : successor_scc_index , annotation : successor_annotation , }) => { trace ! ("Complete; {node:?} is root of complete-visited SCC idx {successor_scc_index:?} with annotation {successor_annotation:?}") ; trace ! (? node , ? successor_scc_index) ; successors_stack . push (successor_scc_index) ; current_component_annotation . update_reachable (successor_annotation) ; } None => { let depth = depth + 1 ; trace ! ("Recursing down into {successor_node:?} at depth {depth:?}") ; trace ! (? depth , ? successor_node) ; frame . successor_node = successor_node ; stack . push (VisitingNodeFrame { node : successor_node , depth , successors : None , successors_len : 0 , min_depth : depth , min_cycle_root : successor_node , successor_node , current_component_annotation : self . annotations . new (successor_node) , }) ; continue 'recurse ; } } } trace ! ("Finished walk from {node:?} with annotation: {current_component_annotation:?}") ; let r = self . node_stack . pop () ; debug_assert_eq ! (r , Some (node)) ; let frame = stack . pop () . unwrap () ; let current_component_annotation = frame . current_component_annotation ; debug_assert_eq ! (frame . node , node) ; debug_assert ! (return_value . is_none ()) ; return_value = Some (if frame . min_depth == depth { let deduplicated_successors = { let duplicate_set = & mut self . duplicate_set ; duplicate_set . clear () ; successors_stack . drain (successors_len ..) . filter (move | & i | duplicate_set . insert (i)) } ; debug ! ("Creating SCC rooted in {node:?} with successor {:?}" , frame . successor_node) ; let scc_index = self . scc_data . create_scc (deduplicated_successors) ; self . annotations . annotate_scc (scc_index , current_component_annotation) ; self . node_states [node] = NodeState :: InCycle { scc_index , annotation : current_component_annotation } ; WalkReturn :: Complete { scc_index , annotation : current_component_annotation } } else { self . node_states [node] = NodeState :: InCycleWith { parent : frame . min_cycle_root } ; WalkReturn :: Cycle { min_depth : frame . min_depth , annotation : current_component_annotation , } }) ; } self . successors_stack = successors_stack ; debug_assert_eq ! (self . successors_stack . len () , 0) ; return_value . unwrap () } }